    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> EventCallback {
        return EventCallbackImpl(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: EventCallback) -> UnsafeMutableRawPointer {
        guard let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: handleMap.insert(obj: value))) else {
            fatalError("Cast to UnsafeMutableRawPointer failed")
        }
        return ptr
