        }
        if lhs.contact != rhs.contact {
            return false
        }
        if lhs.software != rhs.software {
            return false
        }
        if lhs.version != rhs.version {
            return false
        }
        if lhs.supportedNips != rhs.supportedNips {
            return false
        }
        if lhs.icon != rhs.icon {
            return false
